      const nu = maandOp(per, j, schaal) * Math.pow(1.0 + MV.inflatie, j - start); const bedrag = nu * MND * STAP; const uit = Math.min(pot, bedrag); pot -= uit; belegd -= bedrag - uit;
      if (pot + belegd <= 0) return pot + belegd;
